CREATE TABLE transport_payments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY, vehicle_id BIGINT UNSIGNED NULL, driver_id BIGINT UNSIGNED NULL, financial_transaction_id BIGINT UNSIGNED NULL, payment_date DATE NOT NULL, amount DECIMAL(15,2) NOT NULL, description VARCHAR(500) NOT NULL, payment_kind ENUM('trip_revenue','driver_payment','other') NOT NULL, status ENUM('pending','paid','cancelled') NOT NULL DEFAULT 'pending', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, UNIQUE KEY uq_transport_payments_ft (financial_transaction_id), KEY idx_tp_date_kind (payment_date,payment_kind), CONSTRAINT chk_tp_amount CHECK (amount > 0), CONSTRAINT fk_tp_vehicle FOREIGN KEY (vehicle_id) REFERENCES vehicles(id) ON DELETE RESTRICT, CONSTRAINT fk_tp_driver FOREIGN KEY (driver_id) REFERENCES drivers(id) ON DELETE RESTRICT, CONSTRAINT fk_tp_ft FOREIGN KEY (financial_transaction_id) REFERENCES financial_transactions(id) ON DELETE RESTRICT) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
